create extension if not exists pgcrypto;
create table if not exists restaurant_settings(id uuid primary key default gen_random_uuid(),nome text not null default 'Tabajara\'s Churrascaria',logo_url text,cor_primaria text,cor_primaria_dark text,cor_secundaria text,cor_background text,taxa_base_entrega numeric(10,2) not null default 0 check(taxa_base_entrega>=0),valor_minimo_pedido numeric(10,2) not null default 0 check(valor_minimo_pedido>=0),chave_pix text,whatsapp text,tempo_estimado text default '40-60 minutos',horario_funcionamento jsonb not null default '{}'::jsonb,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now());
create table if not exists categories(id uuid primary key default gen_random_uuid(),nome text not null,ordem integer not null default 0,ativo boolean not null default true,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now());
create table if not exists products(id uuid primary key default gen_random_uuid(),category_id uuid not null references categories(id) on delete restrict,nome text not null,descricao text,preco numeric(10,2) not null check(preco>=0),imagem_url text,ativo boolean not null default true,destaque boolean not null default false,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now());
create table if not exists option_groups(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id) on delete cascade,nome text not null,min_select integer not null default 0 check(min_select>=0),max_select integer not null default 1 check(max_select>=min_select),obrigatorio boolean not null default false,ordem integer not null default 0);
create table if not exists options(id uuid primary key default gen_random_uuid(),group_id uuid not null references option_groups(id) on delete cascade,nome text not null,preco_extra numeric(10,2) not null default 0 check(preco_extra>=0),ordem integer not null default 0,ativo boolean not null default true);
create table if not exists addons(id uuid primary key default gen_random_uuid(),nome text not null unique,preco numeric(10,2) not null check(preco>=0),ativo boolean not null default true,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now());
create table if not exists product_addons(product_id uuid not null references products(id) on delete cascade,addon_id uuid not null references addons(id) on delete cascade,primary key(product_id,addon_id));
create table if not exists customers(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,nome text not null,telefone text not null,email text,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now());
create table if not exists addresses(id uuid primary key default gen_random_uuid(),customer_id uuid not null references customers(id) on delete cascade,rotulo text,rua text not null,numero text not null,complemento text,bairro text not null,cidade text not null,cep text not null,referencia text,lat numeric,lng numeric,padrao boolean not null default false,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now());
create table if not exists delivery_zones(id uuid primary key default gen_random_uuid(),nome text not null unique,taxa numeric(10,2) not null check(taxa>=0),ativo boolean not null default true,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now());
create table if not exists coupons(id uuid primary key default gen_random_uuid(),codigo text not null unique,tipo text not null check(tipo in('percentual','fixo')),valor numeric(10,2) not null check(valor>=0),pedido_minimo numeric(10,2) not null default 0 check(pedido_minimo>=0),limite_usos integer,usos_atuais integer not null default 0 check(usos_atuais>=0),validade timestamptz,ativo boolean not null default true,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now());
create table if not exists orders(id uuid primary key default gen_random_uuid(),customer_id uuid not null references customers(id) on delete restrict,address_id uuid references addresses(id) on delete restrict,status text not null default 'recebido' check(status in('recebido','preparando','saiu_para_entrega','entregue','cancelado')),subtotal numeric(10,2) not null check(subtotal>=0),taxa_entrega numeric(10,2) not null default 0 check(taxa_entrega>=0),desconto numeric(10,2) not null default 0 check(desconto>=0),total numeric(10,2) not null check(total>=0),forma_pagamento text not null check(forma_pagamento in('pix','cartao','na_entrega')),status_pagamento text not null default 'pendente' check(status_pagamento in('pendente','confirmado','falhou')),coupon_id uuid references coupons(id) on delete set null,observacoes text,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now());
create table if not exists order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id) on delete cascade,product_id uuid references products(id) on delete set null,quantidade integer not null check(quantidade>0),preco_unitario numeric(10,2) not null check(preco_unitario>=0),opcoes_selecionadas jsonb not null default '[]'::jsonb,adicionais_selecionados jsonb not null default '[]'::jsonb,observacao_item text);
create table if not exists order_status_history(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id) on delete cascade,status text not null check(status in('recebido','preparando','saiu_para_entrega','entregue','cancelado')),motivo_cancelamento text,alterado_em timestamptz not null default now());
create table if not exists payments(id uuid primary key default gen_random_uuid(),order_id uuid not null unique references orders(id) on delete cascade,mp_payment_id text,status text not null default 'pendente' check(status in('pendente','confirmado','falhou')),qr_code text,qr_code_base64 text,valor numeric(10,2) not null check(valor>=0),criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now());
create table if not exists admin_users(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,nome text not null,papel text not null check(papel in('admin','atendente')),criado_em timestamptz not null default now());
create unique index if not exists restaurant_settings_singleton on restaurant_settings((true));
create index if not exists idx_products_category_id on products(category_id);create index if not exists idx_orders_customer_id on orders(customer_id);create index if not exists idx_orders_status on orders(status);create index if not exists idx_orders_payment_status on orders(status_pagamento);create index if not exists idx_order_items_order_id on order_items(order_id);create index if not exists idx_status_history_order_id on order_status_history(order_id,alterado_em);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admin_users where user_id=auth.uid()); $$;
create or replace function public.prevent_customer_order_status_change() returns trigger language plpgsql security definer set search_path=public as $$ begin if not public.is_admin() and new.status is distinct from old.status then raise exception 'Cliente não pode alterar status do pedido'; end if; return new; end; $$;
drop trigger if exists trg_prevent_customer_order_status_change on public.orders;create trigger trg_prevent_customer_order_status_change before update on public.orders for each row execute function public.prevent_customer_order_status_change();
alter table restaurant_settings enable row level security;alter table categories enable row level security;alter table products enable row level security;alter table option_groups enable row level security;alter table options enable row level security;alter table addons enable row level security;alter table product_addons enable row level security;alter table customers enable row level security;alter table addresses enable row level security;alter table delivery_zones enable row level security;alter table coupons enable row level security;alter table orders enable row level security;alter table order_items enable row level security;alter table order_status_history enable row level security;alter table payments enable row level security;alter table admin_users enable row level security;
create policy restaurant_public_read on restaurant_settings for select using(true);create policy restaurant_admin_write on restaurant_settings for all using(public.is_admin()) with check(public.is_admin());create policy categories_public_read on categories for select using(ativo=true);create policy categories_admin_write on categories for all using(public.is_admin()) with check(public.is_admin());create policy products_public_read on products for select using(ativo=true);create policy products_admin_write on products for all using(public.is_admin()) with check(public.is_admin());create policy option_groups_public_read on option_groups for select using(exists(select 1 from products p where p.id=product_id and p.ativo=true));create policy option_groups_admin_write on option_groups for all using(public.is_admin()) with check(public.is_admin());create policy options_public_read on options for select using(ativo=true and exists(select 1 from option_groups g join products p on p.id=g.product_id where g.id=group_id and p.ativo=true));create policy options_admin_write on options for all using(public.is_admin()) with check(public.is_admin());create policy addons_public_read on addons for select using(ativo=true);create policy addons_admin_write on addons for all using(public.is_admin()) with check(public.is_admin());create policy product_addons_public_read on product_addons for select using(exists(select 1 from products p where p.id=product_id and p.ativo=true) and exists(select 1 from addons a where a.id=addon_id and a.ativo=true));create policy product_addons_admin_write on product_addons for all using(public.is_admin()) with check(public.is_admin());create policy delivery_public_read on delivery_zones for select using(ativo=true);create policy delivery_admin_write on delivery_zones for all using(public.is_admin()) with check(public.is_admin());
create policy customers_self_select on customers for select using(user_id=auth.uid());create policy customers_self_insert on customers for insert with check(user_id=auth.uid());create policy customers_self_update on customers for update using(user_id=auth.uid()) with check(user_id=auth.uid());create policy customers_admin_all on customers for all using(public.is_admin()) with check(public.is_admin());create policy addresses_self_select on addresses for select using(exists(select 1 from customers c where c.id=customer_id and c.user_id=auth.uid()));create policy addresses_self_insert on addresses for insert with check(exists(select 1 from customers c where c.id=customer_id and c.user_id=auth.uid()));create policy addresses_self_update on addresses for update using(exists(select 1 from customers c where c.id=customer_id and c.user_id=auth.uid())) with check(exists(select 1 from customers c where c.id=customer_id and c.user_id=auth.uid()));create policy addresses_self_delete on addresses for delete using(exists(select 1 from customers c where c.id=customer_id and c.user_id=auth.uid()));create policy addresses_admin_all on addresses for all using(public.is_admin()) with check(public.is_admin());
create policy orders_self_select on orders for select using(exists(select 1 from customers c where c.id=customer_id and c.user_id=auth.uid()));create policy orders_self_insert on orders for insert with check(exists(select 1 from customers c where c.id=customer_id and c.user_id=auth.uid()));create policy orders_admin_all on orders for all using(public.is_admin()) with check(public.is_admin());
create policy order_items_self_select on order_items for select using(exists(select 1 from orders o join customers c on c.id=o.customer_id where o.id=order_id and c.user_id=auth.uid()));create policy order_items_self_insert on order_items for insert with check(exists(select 1 from orders o join customers c on c.id=o.customer_id where o.id=order_id and c.user_id=auth.uid()));create policy order_items_admin_all on order_items for all using(public.is_admin()) with check(public.is_admin());
create policy status_history_self_select on order_status_history for select using(exists(select 1 from orders o join customers c on c.id=o.customer_id where o.id=order_id and c.user_id=auth.uid()));create policy status_history_admin_all on order_status_history for all using(public.is_admin()) with check(public.is_admin());create policy payments_self_select on payments for select using(exists(select 1 from orders o join customers c on c.id=o.customer_id where o.id=order_id and c.user_id=auth.uid()));create policy payments_admin_all on payments for all using(public.is_admin()) with check(public.is_admin());create policy admin_users_self_select on admin_users for select using(user_id=auth.uid() or public.is_admin());create policy admin_users_admin_write on admin_users for all using(public.is_admin()) with check(public.is_admin());
create or replace function public.validar_cupom(codigo text,valor_pedido numeric) returns table(valido boolean,tipo text,valor numeric,desconto numeric) language sql stable security definer set search_path=public as $$ select true,c.tipo,c.valor,case when c.tipo='percentual' then least(valor_pedido,round(valor_pedido*c.valor/100,2)) else least(valor_pedido,c.valor) end from public.coupons c where upper(c.codigo)=upper(trim(validar_cupom.codigo)) and c.ativo=true and(c.validade is null or c.validade>now()) and(c.limite_usos is null or c.usos_atuais<c.limite_usos) and valor_pedido>=c.pedido_minimo limit 1; $$;
create or replace function public.consumir_cupom(codigo text,valor_pedido numeric) returns boolean language plpgsql security definer set search_path=public as $$ declare v_id uuid;begin select id into v_id from coupons where upper(coupons.codigo)=upper(trim(consumir_cupom.codigo)) and ativo=true and(validade is null or validade>now()) and(limite_usos is null or usos_atuais<limite_usos) and valor_pedido>=pedido_minimo for update;if v_id is null then return false;end if;update coupons set usos_atuais=usos_atuais+1,atualizado_em=now() where id=v_id;return true;end; $$;
grant execute on function public.validar_cupom(text,numeric) to anon,authenticated;grant execute on function public.consumir_cupom(text,numeric) to authenticated;
